(()=>{
function wav(samples,rate){const data=new ArrayBuffer(44+samples.length*2),view=new DataView(data);const text=(at,value)=>{for(let i=0;i<value.length;i++)view.setUint8(at+i,value.charCodeAt(i))};text(0,'RIFF');view.setUint32(4,36+samples.length*2,true);text(8,'WAVE');text(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,rate,true);view.setUint32(28,rate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,samples.length*2,true);for(let i=0;i<samples.length;i++){const v=Math.max(-1,Math.min(1,samples[i]));view.setInt16(44+i*2,Math.round(v*(v<0?32768:32767)),true)}return new Blob([data],{type:'audio/wav'})}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function renderMix(tones,seconds,volume,normalizationSum){const rate=44100,Offline=window.OfflineAudioContext||window.webkitOfflineAudioContext;if(!Offline)throw new Error('Offline audio rendering is unavailable');const context=new Offline(1,Math.round(rate*seconds),rate),sum=normalizationSum??tones.reduce((total,t)=>total+t.a,0);for(const t of tones){const oscillator=context.createOscillator(),gain=context.createGain();oscillator.type='sine';oscillator.frequency.value=t.f;const level=sum>0?volume*t.a/sum:0,fade=Math.min(.025,seconds/4);gain.gain.setValueAtTime(0,0);gain.gain.linearRampToValueAtTime(level,fade);gain.gain.setValueAtTime(level,seconds-fade);gain.gain.linearRampToValueAtTime(0,seconds);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(0);oscillator.stop(seconds)}return context.startRendering()}
window.HarmonicAudio={wav,download,renderMix};
})();
